import React from 'react';
import type { Wall, Door } from '../../core/types';
import { useSectionPlanes } from './SectionContext';
import { MainDoorLaserCut } from './MainDoorLaserCut';
interface Props {
  wall: Wall;
    door: Door;
      color?: string;
        openAngleDeg?: number;
          mainDoorFrameColor?: string;
            mainDoorSheetColor?: string;
              mainDoorPatternColor?: string;
                shopDoorColor?: string;
                  shopDoorSlatCount?: number;
                    shopBaseColor?: string;
                      windowFrameColor?: string;
                        windowGlassColor?: string;
                          windowGlassOpacity?: number;
                            elevation?: number;
                            }
                            export const Door3D: React.FC<Props> = ({
                              wall,
                                door,
                                  color = '#8B5A2B',
                                    openAngleDeg = 80,
                                      mainDoorFrameColor = '#9a9a9a',
                                        mainDoorSheetColor = '#1a1a1a',
                                          mainDoorPatternColor = '#e8e8e8',
                                            shopDoorColor = '#9a9a9a',
                                              shopDoorSlatCount = 20,
                                                shopBaseColor = '#E8E4DC',
                                                  windowFrameColor = '#000000',
                                                    windowGlassColor = '#87CEEB',
                                                      windowGlassOpacity = 0.90,
                                                        elevation = 0,
                                                        }) => {
                                                          const clippingPlanes = useSectionPlanes();
                                                            const dx = wall.end.x - wall.start.x;
                                                              const dy = wall.end.y - wall.start.y;
                                                                const len = Math.hypot(dx, dy) || 1;
                                                                  const cx = door.center?.x ?? (wall.start.x + ((door.position + door.width / 2) / len) * dx);
                                                                    const cy = door.center?.y ?? (wall.start.y + ((door.position + door.width / 2) / len) * dy);
                                                                      const rot = door.rotation ?? Math.atan2(dy, dx);
                                                                        const doorType = door.doorType ?? 'regular';
                                                                          const ux = dx / len;
                                                                            const uy = dy / len;
                                                                              const nx = -uy;
                                                                                const ny = ux;
                                                                                  const sign = wall.normalSign ?? 1;
                                                                                    const halfTh = wall.thickness / 2;
                                                                                      // ======================================================
                                                                                        // 🏪 باب محل
                                                                                          // ======================================================
                                                                                            if (doorType === 'shop') {
                                                                                                const TOP_BAND_H = 0.20;
                                                                                                    const WINDOW_H = 0.40;
                                                                                                        const CONSTRUCTION_H = 0.40;
                                                                                                            const SHUTTER_TOP = Math.max(0.3, door.height - TOP_BAND_H - WINDOW_H - CONSTRUCTION_H);
                                                                                                                const CONSTRUCTION_START = SHUTTER_TOP;
                                                                                                                    const WINDOW_START = SHUTTER_TOP + CONSTRUCTION_H;
                                                                                                                        const TOP_BAND_START = WINDOW_START + WINDOW_H;
                                                                                                                            const SLAT_COUNT = Math.max(8, shopDoorSlatCount);
                                                                                                                                const slatH = SHUTTER_TOP / SLAT_COUNT;
                                                                                                                                    const slatColor = shopDoorColor;
                                                                                                                                        const slatDark = '#7a7a7a';
                                                                                                                                            const FRAME_T = 0.05;
                                                                                                                                                const FRAME_D = 0.06;
                                                                                                                                                    const MULLION_W = 0.04;
                                                                                                                                                        const INNER_W = door.width - FRAME_T * 2;
                                                                                                                                                            const MULLION_XS = [
                                                                                                                                                                  -INNER_W / 2 + INNER_W / 4,
                                                                                                                                                                        -INNER_W / 2 + INNER_W / 2,
                                                                                                                                                                              -INNER_W / 2 + (INNER_W * 3) / 4,
                                                                                                                                                                                  ];
                                                                                                                                                                                      const COLUMN_W = 0.20;
                                                                                                                                                                                          const COLUMN_PROTRUDE = 0.08;
                                                                                                                                                                                              const COLUMN_DEPTH = wall.thickness + COLUMN_PROTRUDE * 2;
                                                                                                                                                                                                  const zFront = COLUMN_DEPTH / 2;
                                                                                                                                                                                                      const STONE_PROUD = 0.20;
                                                                                                                                                                                                          const STONE_RECESSED = 0.10;
                                                                                                                                                                                                              const STONE_PROUD_DEPTH = 0.015;
                                                                                                                                                                                                                  const STONE_RECESSED_DEPTH = 0.005;
                                                                                                                                                                                                                      const stones: { x: number; w: number; depth: number; proud: boolean }[] = [];
                                                                                                                                                                                                                          let px = -door.width / 2;
                                                                                                                                                                                                                              let isProud = true;
                                                                                                                                                                                                                                  while (px < door.width / 2 - 0.001) {
                                                                                                                                                                                                                                        const w = isProud ? STONE_PROUD : STONE_RECESSED;
                                                                                                                                                                                                                                              const d = isProud ? STONE_PROUD_DEPTH : STONE_RECESSED_DEPTH;
                                                                                                                                                                                                                                                    const remaining = door.width / 2 - px;
                                                                                                                                                                                                                                                          const actualW = Math.min(w, remaining);
                                                                                                                                                                                                                                                                if (actualW < 0.005) break;
                                                                                                                                                                                                                                                                      stones.push({ x: px + actualW / 2, w: actualW, depth: d, proud: isProud });
                                                                                                                                                                                                                                                                            px += actualW;
                                                                                                                                                                                                                                                                                  isProud = !isProud;
                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                          const V_LINE_OFFSETS = [-0.05, 0, 0.05];
                                                                                                                                                                                                                                                                                              const V_LINE_W = 0.008;
                                                                                                                                                                                                                                                                                                  const V_LINE_D = 0.008;
                                                                                                                                                                                                                                                                                                      const H_LINE_OFFSETS = [-0.05, 0, 0.05];
                                                                                                                                                                                                                                                                                                          const H_LINE_H = 0.008;
                                                                                                                                                                                                                                                                                                              const H_LINE_D = 0.008;
                                                                                                                                                                                                                                                                                                                  const CARVE_COLOR = '#5a5248';
                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                            <group position={[cx, elevation, cy]} rotation={[0, -rot, 0]}>
{Array.from({ length: SLAT_COUNT }).map((_, i) => (
    <mesh key={i} position={[0, slatH * (i + 0.5), 0]} castShadow={false} receiveShadow={false}>
        <boxGeometry args={[door.width, slatH * 0.92, 0.05]} />
            <meshStandardMaterial
                  color={slatColor}
                        metalness={0.35}
                              roughness={0.5}
                                    clippingPlanes={clippingPlanes}
                                        />
                                          </mesh>
                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <mesh position={[0, slatH * 0.4, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <boxGeometry args={[door.width + 0.02, 0.06, 0.06]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color={slatDark}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                metalness={0.5}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            roughness={0.4}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <mesh position={[0, CONSTRUCTION_START + CONSTRUCTION_H / 2, 0]} castShadow>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <boxGeometry args={[door.width, CONSTRUCTION_H, COLUMN_DEPTH]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color={shopBaseColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              roughness={0.55}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          metalness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {stones.map((s, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      key={`stone-${i}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  position={[s.x, CONSTRUCTION_START + CONSTRUCTION_H / 2, zFront + s.depth / 2]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <boxGeometry args={[s.w, CONSTRUCTION_H - 0.02, s.depth]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color={s.proud ? shopBaseColor : '#d0c8b8'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                roughness={s.proud ? 0.45 : 0.95}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              metalness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <mesh position={[0, WINDOW_START + FRAME_T / 2, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <boxGeometry args={[door.width, FRAME_T, FRAME_D]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial color={windowFrameColor} roughness={0.4} metalness={0.1} clippingPlanes={clippingPlanes} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <mesh position={[0, WINDOW_START + WINDOW_H - FRAME_T / 2, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <boxGeometry args={[door.width, FRAME_T, FRAME_D]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <meshStandardMaterial color={windowFrameColor} roughness={0.4} metalness={0.1} clippingPlanes={clippingPlanes} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <mesh position={[-door.width / 2 + FRAME_T / 2, WINDOW_START + WINDOW_H / 2, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <boxGeometry args={[FRAME_T, WINDOW_H, FRAME_D]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <meshStandardMaterial color={windowFrameColor} roughness={0.4} metalness={0.1} clippingPlanes={clippingPlanes} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <mesh position={[door.width / 2 - FRAME_T / 2, WINDOW_START + WINDOW_H / 2, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <boxGeometry args={[FRAME_T, WINDOW_H, FRAME_D]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <meshStandardMaterial color={windowFrameColor} roughness={0.4} metalness={0.1} clippingPlanes={clippingPlanes} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {MULLION_XS.map((mx, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        key={`mullion-${i}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    position={[mx, WINDOW_START + WINDOW_H / 2, 0]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <boxGeometry args={[MULLION_W, WINDOW_H - FRAME_T * 2, FRAME_D * 0.9]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial color={windowFrameColor} roughness={0.4} metalness={0.1} clippingPlanes={clippingPlanes} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <mesh position={[0, WINDOW_START + WINDOW_H / 2, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <boxGeometry args={[door.width - FRAME_T * 2, WINDOW_H - FRAME_T * 2, 0.01]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color={windowGlassColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            transparent
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        opacity={windowGlassOpacity}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    roughness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                metalness={0.1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <mesh position={[0, TOP_BAND_START + TOP_BAND_H / 2, 0]} castShadow>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <boxGeometry args={[door.width, TOP_BAND_H, COLUMN_DEPTH]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color={shopBaseColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  roughness={0.45}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              metalness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {H_LINE_OFFSETS.map((yOff, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          key={`hline-${i}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      position={[0, TOP_BAND_START + TOP_BAND_H / 2 + yOff, zFront + H_LINE_D / 2]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <boxGeometry args={[door.width - 0.04, H_LINE_H, H_LINE_D]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color={CARVE_COLOR}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    roughness={0.9}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  metalness={0}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {[-1, 1].map((side) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const colX = side * (door.width / 2 + COLUMN_W / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <React.Fragment key={side}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <mesh position={[colX, door.height / 2, 0]} castShadow>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <boxGeometry args={[COLUMN_W, door.height, COLUMN_DEPTH]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color={shopBaseColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        roughness={0.45}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          metalness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {V_LINE_OFFSETS.map((xOff, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         key={`vline-${side}-${i}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           position={[colX + xOff, door.height / 2, zFront + V_LINE_D / 2]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <boxGeometry args={[V_LINE_W, door.height - 0.04, V_LINE_D]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   color={CARVE_COLOR}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       roughness={0.9}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           metalness={0}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </React.Fragment>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // ======================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // 🕌 باب رئيسي
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // ======================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (doorType === 'main') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const openingStart = (() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (!door.center) return door.position;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const cxAlong = (door.center.x - wall.start.x) * ux + (door.center.y - wall.start.y) * uy;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return cxAlong - door.width / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           })();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const midDist = openingStart + door.width / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const midX = wall.start.x + ux * midDist + nx * halfTh * sign;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const midY = wall.start.y + uy * midDist + ny * halfTh * sign;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <group position={[midX, elevation, midY]} rotation={[0, -rot, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <MainDoorLaserCut
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   width={door.width}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             height={door.height}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       frameColor={mainDoorFrameColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 sheetColor={mainDoorSheetColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           patternColor={mainDoorPatternColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // ======================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // 🚪 باب عادي
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // ======================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const cosR = Math.cos(rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const sinR = Math.sin(rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const hxLocal = door.hinge === 'start' ? -door.width / 2 : door.width / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const closedSign = door.hinge === 'start' ? 1 : -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const swingSign = door.swing || 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const thetaSigned = (openAngleDeg * Math.PI / 180) * closedSign * swingSign;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const dirWorldX = closedSign * Math.cos(thetaSigned + rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const dirWorldY = closedSign * Math.sin(thetaSigned + rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const hingeWorldX = cx + hxLocal * cosR;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const hingeWorldY = cy + hxLocal * sinR;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const leafCenterX = hingeWorldX + dirWorldX * (door.width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const leafCenterY = hingeWorldY + dirWorldY * (door.width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const leafRotY = Math.atan2(-dirWorldY, dirWorldX);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const doorThickness = 0.05;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               position={[leafCenterX, door.height / 2, leafCenterY]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       rotation={[0, leafRotY, 0]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <boxGeometry args={[door.width, door.height, doorThickness]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       color={color}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 roughness={0.7}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       position={[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 hingeWorldX + dirWorldX * door.width * 0.88,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           door.height * 0.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     hingeWorldY + dirWorldY * door.width * 0.88,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           <sphereGeometry args={[0.04, 12, 12]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             color="#FFD700"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       metalness={0.85}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 roughness={0.15}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           clippingPlanes={clippingPlanes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               };